package dev.rakrecorder;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.Bundle;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    private static final int PICK=1, SAVE=2, VPN_PERMISSION=3;
    private String selectedPackage;
    private final BroadcastReceiver captureReceiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){int status=i.getIntExtra("status",-99);showHome();new AlertDialog.Builder(MainActivity.this).setTitle(status==0?"Запись завершена":"Запись остановлена с ошибкой").setMessage(status==0?"Сессия сохранена локально.":"Код: "+status+". "+i.getStringExtra("error")).setPositiveButton("OK",null).show();}};
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private SessionStore store; private LinearLayout body; private String selected; private boolean exportRaw;
    @Override public void onCreate(Bundle state) {super.onCreate(state);store=new SessionStore(this);if(state!=null){selected=state.getString("selected");selectedPackage=state.getString("package");} if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(captureReceiver,new IntentFilter("dev.rakrecorder.CAPTURE_FINISHED"),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(captureReceiver,new IntentFilter("dev.rakrecorder.CAPTURE_FINISHED"));showHome();}
    @Override protected void onSaveInstanceState(Bundle state){state.putString("selected",selected);state.putString("package",selectedPackage);super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){unregisterReceiver(captureReceiver);io.shutdown();super.onDestroy();}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextColor(color);t.setTextSize(size);t.setPadding(0,12,0,12);return t;}
    private void frame(String title) {LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(30,34,30,20);root.setBackgroundColor(0xff140d24);root.addView(text(title,25,Color.WHITE));ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll);setContentView(root);}
    private void label(String s){body.addView(text(s,16,0xffe0d6ed));}
    private void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);body.addView(b);b.setOnClickListener(v->action.run());}
    private void error(Exception e){new AlertDialog.Builder(this).setTitle("Ошибка").setMessage(e.getMessage()==null?e.toString():e.getMessage()).setPositiveButton("OK",null).show();}
    private void showHome(){frame("RakRecorder Studio · альфа");label("Локальные сессии PCAP\nVPN-захват экспериментальный и ещё не проверен на устройстве. Автоматическое определение маршрута пока недоступно.");button("Выбрать игру и начать запись",this::chooseApp);button("Указать имя пакета вручную",this::startCaptureDialog);button("Показать панель поверх игры",this::showOverlay);button("Остановить запись",()->startService(new Intent(this,RecorderVpnService.class).setAction(RecorderVpnService.ACTION_STOP)));button("Импортировать PCAP",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");startActivityForResult(i,PICK);});File[] unfinished=getFilesDir().listFiles((dir,name)->name.startsWith("unfinished-capture-") && name.endsWith(".pcap"));if(!RecorderVpnService.isRunning() && unfinished!=null)for(File raw:unfinished)button("Восстановить незавершённую запись",()->recoverCapture(raw));List<JSONObject> sessions=store.list();if(sessions.isEmpty())label("Сессий пока нет.");for(JSONObject s:sessions){String id=s.optString("session_id");button("Сессия "+s.optString("created_utc")+" · пакетов: "+s.optLong("packets"),()->{selected=id;showSession();});}}
    private void recoverCapture(File raw){frame("Восстановление…");io.execute(()->{try(InputStream in=new FileInputStream(raw)){String id=store.importPcap(in,"live_vpn");File marks=new File(raw.getAbsolutePath()+".markers");RecorderVpnService.importMarkers(store,id,marks);marks.delete();if(!raw.delete()) throw new IOException("Сессия импортирована, но исходный временный файл не удалён");runOnUiThread(()->{selected=id;showSession();});}catch(Exception e){runOnUiThread(()->{showHome();error(e);});}});}
    private void showOverlay(){if(!RecorderVpnService.isRunning()){error(new IllegalStateException("Сначала запустите запись"));return;}if(!android.provider.Settings.canDrawOverlays(this)){new AlertDialog.Builder(this).setTitle("Разрешение на панель").setMessage("Разрешите приложению показывать элементы поверх игры, затем вернитесь и нажмите кнопку панели ещё раз.").setNegativeButton("Отмена",null).setPositiveButton("Настройки",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())))).show();return;}startService(new Intent(this,RecorderVpnService.class).setAction(RecorderVpnService.ACTION_OVERLAY));}
    private void chooseApp(){Intent query=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<android.content.pm.ResolveInfo> apps=getPackageManager().queryIntentActivities(query,0);java.util.Collections.sort(apps,(a,b)->a.loadLabel(getPackageManager()).toString().compareToIgnoreCase(b.loadLabel(getPackageManager()).toString()));java.util.ArrayList<String> labels=new java.util.ArrayList<>(),packages=new java.util.ArrayList<>();for(android.content.pm.ResolveInfo info:apps){String name=info.activityInfo.packageName;if(name.equals(getPackageName())||packages.contains(name))continue;packages.add(name);labels.add(info.loadLabel(getPackageManager()).toString()+" · "+name);}if(packages.isEmpty()){startCaptureDialog();return;}new AlertDialog.Builder(this).setTitle("Какое приложение записывать?").setItems(labels.toArray(new String[0]),(d,index)->{selectedPackage=packages.get(index);startCaptureDialog();}).setNegativeButton("Отмена",null).show();}
    private void startCaptureDialog(){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Имя пакета игры, например com.example.game");if(selectedPackage!=null)input.setText(selectedPackage);new AlertDialog.Builder(this).setTitle("Локальная запись трафика").setMessage("Укажите точное имя установленного приложения. Движок использует локальный VPN без удалённого сервера. Эта функция экспериментальная.").setView(input).setNegativeButton("Отмена",null).setPositiveButton("Продолжить",(d,w)->{selectedPackage=input.getText().toString().trim();if(selectedPackage.isEmpty()){error(new IllegalArgumentException("Укажите имя пакета"));return;}Intent permission=android.net.VpnService.prepare(this);if(permission!=null)startActivityForResult(permission,VPN_PERMISSION);else beginCapture();}).show();}
    private void beginCapture(){try{Intent service=new Intent(this,RecorderVpnService.class).setAction(RecorderVpnService.ACTION_START).putExtra("package",selectedPackage);startForegroundService(service);Toast.makeText(this,"Запуск VPN-записи",Toast.LENGTH_LONG).show();}catch(Exception e){error(e);}}
    private void showSession(){try {JSONObject s=store.read(selected);frame("Сессия");button("← Все сессии",this::showHome);label("Импорт: "+s.optString("created_utc")+"\nПакетов: "+s.getLong("packets")+"\nUDP: "+s.getLong("udp")+" · TCP: "+s.getLong("tcp")+"\nUDP порт 5125: "+s.getLong("udp_5125")+" · порт 5127: "+s.getLong("udp_5127")+"\nПервый пакет: "+format(s.getLong("first_us"))+"\nПоследний пакет: "+format(s.getLong("last_us"))+"\n\nXYZ и игровые события не декодированы. Порт сам по себе не подтверждает принадлежность к игре.");button("Добавить ручную отметку",this::markerDialog);JSONArray m=s.getJSONArray("markers");label("Отметки: "+m.length());for(int i=0;i<m.length();i++){JSONObject x=m.getJSONObject(i);label((i+1)+". "+x.getString("type")+" · "+x.getLong("time_ms")+" мс\n"+x.optString("note")+"\nКоординаты: неизвестно");}if(m.length()>0)button("Отменить последнюю отметку",()->{try{JSONObject q=store.read(selected);JSONArray a=q.getJSONArray("markers");a.remove(a.length()-1);store.write(selected,q);showSession();}catch(Exception e){error(e);}});button("Экспортировать ZIP",this::exportDialog);button("Удалить сессию",()->new AlertDialog.Builder(this).setTitle("Удалить сессию?").setMessage("Локальная копия PCAP и отметки будут удалены.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{try{store.delete(selected);selected=null;showHome();}catch(Exception e){error(e);}}).show());}catch(Exception e){selected=null;error(e);showHome();}}
    private void markerDialog(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(25,10,25,0);Spinner type=new Spinner(this);String[] types={"Точка","Начало мини-игры","Конец мини-игры","Событие","Комментарий"};type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,types));form.addView(type);EditText seconds=new EditText(this);seconds.setHint("Секунды от первого пакета");seconds.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);form.addView(seconds);EditText note=new EditText(this);note.setHint("Комментарий (необязательно)");form.addView(note);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ручная отметка").setView(form).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{double sec=Double.parseDouble(seconds.getText().toString());if(!Double.isFinite(sec)||sec<0||sec>Long.MAX_VALUE/1000d)throw new IllegalArgumentException("Укажите корректное время");store.addMarker(selected,types[type.getSelectedItemPosition()],note.getText().toString(),(long)(sec*1000));dialog.dismiss();showSession();}catch(Exception e){error(e);}}));dialog.show();}
    private void exportDialog(){CheckBox raw=new CheckBox(this);raw.setText("Включить исходный PCAP (может содержать чувствительные данные)");new AlertDialog.Builder(this).setTitle("Экспорт сессии").setMessage("Архив содержит отметки и диагностику. Координаты не определены.").setView(raw).setNegativeButton("Отмена",null).setPositiveButton("Выбрать файл",(d,w)->{exportRaw=raw.isChecked();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"RakRecorder-"+selected.substring(0,8)+".zip");startActivityForResult(i,SAVE);}).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VPN_PERMISSION){if(result==RESULT_OK)beginCapture();return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==PICK){frame("Импорт…");label("Не закрывайте приложение во время обработки.");io.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Не удалось открыть файл");String id=store.importPcap(in);runOnUiThread(()->{selected=id;showSession();});}catch(Exception e){runOnUiThread(()->{showHome();error(e);});}});}else if(request==SAVE){String id=selected;boolean raw=exportRaw;io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("Не удалось открыть файл для записи");store.export(id,raw,out);runOnUiThread(()->Toast.makeText(this,"ZIP сохранён",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->error(e));}});}}
    private String format(long t){return t<0?"нет":Instant.ofEpochSecond(t/1000000,(t%1000000)*1000).toString();}
}
